INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `hidden`, `created_at`, `updated_at`) VALUES
(1, 'all', 'هل التسجيل مجاني أم يحتاج إلى رسوم؟', 'التسجيل في المنصة مجاني تماماً، بحيث يمكنك إنشاء حساب والاطلاع على معظم المحتويات الأساسية بدون أي رسوم. ولكن بعض الدورات أو البرامج التدريبية المتقدمة قد تكون مدفوعة، وذلك لضمان جودة المحتوى واستمرارية المنصة. ومع ذلك، نوفر دائماً عدداً من الدورات المجانية ليتمكن الجميع من الاستفادة وتجربة المنصة قبل الاشتراك في البرامج المدفوعة.\r\n', 0, NULL, NULL),
(2, 'general_aptitude', 'هل يمكن استرجاع رسوم الدورة في حال لم تعجبني؟', 'نعم، يمكنك طلب استرجاع الرسوم خلال 7 أيام من تاريخ الدفع إذا لم تبدأ الدورة، وفقاً لسياسة الاسترجاع الخاصة بنا.\r\n', 0, NULL, NULL);
