(3858, 1106, '<p><span style=\"color: rgb(31, 41, 55); background-color: rgb(255, 255, 255);\">القاهرة</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">القاهرة&nbsp;هي&nbsp;عاصمة&nbsp;مصر&nbsp;الرسمية،&nbsp;وتضم&nbsp;مقر&nbsp;الحكومة&nbsp;والبرلمان&nbsp;ورئاسة&nbsp;الدولة،&nbsp;وهي&nbsp;أكبر&nbsp;مدينة&nbsp;في&nbsp;مصر&nbsp;من&nbsp;حيث&nbsp;عدد&nbsp;السكان.</span></p>', NULL, NULL),
(3859, 1106, '<p><span style=\"background-color: rgb(249, 250, 251); color: rgb(31, 41, 55);\">أسوان</span></p>', 0, '', NULL, NULL),
(3860, 1107, '<p><span style=\"background-color: rgb(249, 250, 251); color: rgb(31, 41, 55);\">المريخ</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">يُسمّى&nbsp;كوكب&nbsp;</span><strong style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(230, 0, 0);\"><u>المريخ&nbsp;</u></strong><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">بالكوكب&nbsp;الأحمر&nbsp;بسبب&nbsp;انتشار&nbsp;أكسيد&nbsp;الحديد&nbsp;على&nbsp;سطحه،&nbsp;مما&nbsp;يعطيه&nbsp;اللون&nbsp;الأحمر&nbsp;المميز.</span></p><p></p>', NULL, NULL),
(3861, 1107, '<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(31, 41, 55);\">الزهرة</span></p>', 0, '', NULL, NULL),
