(3866, 1108, '<p><span style=\"background-color: rgb(249, 250, 251); color: rgb(31, 41, 55);\">التجارة</span></p>', 0, '', NULL, NULL),
(3867, 1108, '<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(31, 41, 55);\">العلم</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">ذكر&nbsp;النص&nbsp;في&nbsp;بدايته&nbsp;أن&nbsp;العلم&nbsp;هو&nbsp;أساس&nbsp;تقدّم&nbsp;الأمم&nbsp;وازدهارها،&nbsp;لأنه&nbsp;يساعد&nbsp;الإنسان&nbsp;على&nbsp;فهم&nbsp;العالم&nbsp;وتطوير&nbsp;حياته.</span></p>', NULL, NULL),
(3868, 1109, '<p><span style=\"background-color: rgb(249, 250, 251); color: rgb(31, 41, 55);\">أمر&nbsp;اختياري</span></p>', 0, '', NULL, NULL),
(3869, 1109, '<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(31, 41, 55);\">فريضة&nbsp;على&nbsp;كل&nbsp;مسلم&nbsp;ومسلمة</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">أوضح&nbsp;النص&nbsp;أن&nbsp;الإسلام&nbsp;حثّ&nbsp;على&nbsp;طلب&nbsp;العلم&nbsp;وجعله&nbsp;فريضة،&nbsp;أي&nbsp;واجبًا&nbsp;على&nbsp;جميع&nbsp;المسلمين&nbsp;دون&nbsp;استثناء.</span></p>', NULL, NULL),
(3870, 1109, '<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(31, 41, 55);\">خاص&nbsp;بالعلماء&nbsp;فقط</span></p>', 0, '', NULL, NULL),
