(4357, 1193, '<p>نشر&nbsp;الوعي</p>', 1, '<p>أوضح&nbsp;النص&nbsp;أن&nbsp;العلم&nbsp;يساعد&nbsp;على&nbsp;نشر&nbsp;الوعي،&nbsp;ومن&nbsp;خلال&nbsp;الوعي&nbsp;يتم&nbsp;محاربة&nbsp;الجهل&nbsp;في&nbsp;المجتمعات.</p>', NULL, NULL),
(4358, 1193, '<p>إضاعة&nbsp;الوقت</p>', 0, '', NULL, NULL),
