(4365, 1195, '<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(31, 41, 55);\">الجيزة</span></p>', 0, '<p></p>', NULL, NULL),
(4366, 1195, '<p><span style=\"color: rgb(31, 41, 55); background-color: rgb(255, 255, 255);\">القاهرة</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">القاهرة&nbsp;هي&nbsp;عاصمة&nbsp;مصر&nbsp;الرسمية،&nbsp;وتضم&nbsp;مقر&nbsp;الحكومة&nbsp;والبرلمان&nbsp;ورئاسة&nbsp;الدولة،&nbsp;وهي&nbsp;أكبر&nbsp;مدينة&nbsp;في&nbsp;مصر&nbsp;من&nbsp;حيث&nbsp;عدد&nbsp;السكان.</span></p>', NULL, NULL),
