(4368, 1196, '<p><span style=\"background-color: rgb(249, 250, 251); color: rgb(31, 41, 55);\">المريخ</span></p>', 1, '<p><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">يُسمّى&nbsp;كوكب&nbsp;</span><strong style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(230, 0, 0);\"><u>المريخ&nbsp;</u></strong><span style=\"background-color: rgba(249, 250, 251, 0.7); color: rgb(75, 85, 99);\">بالكوكب&nbsp;الأحمر&nbsp;بسبب&nbsp;انتشار&nbsp;أكسيد&nbsp;الحديد&nbsp;على&nbsp;سطحه،&nbsp;مما&nbsp;يعطيه&nbsp;اللون&nbsp;الأحمر&nbsp;المميز.</span></p><p></p>', NULL, NULL),
