INSERT INTO `round_terms` (`id`, `round_id`, `title`, `points`, `created_at`, `updated_at`) VALUES
(15, 310, 'الشروط والأحكام العامة', '[\"الالتزام بمواعيد الحضور.\",\"الدفع غير قابل للاسترداد بعد بدء الجولة.\",\"احترام سياسة المنصة والمدربين.\"]', '2025-11-17 13:47:55', '2025-11-17 13:47:55'),
(16, 310, 'سياسة الإلغاء', '[\"يمكن الإلغاء قبل 48 ساعة من البداية.\",\"قد تُطبق رسوم إدارية على بعض الحالات.\"]', '2025-11-17 13:47:55', '2025-11-17 13:47:55'),
(17, 313, 'الشروط والأحكام العامة', '[\"الالتزام بمواعيد الحضور.\",\"الدفع غير قابل للاسترداد بعد بدء الجولة.\",\"احترام سياسة المنصة والمدربين.\"]', '2025-11-19 09:05:42', '2025-11-19 09:05:42'),
(18, 313, 'سياسة الإلغاء', '[\"يمكن الإلغاء قبل 48 ساعة من البداية.\",\"قد تُطبق رسوم إدارية على بعض الحالات.\"]', '2025-11-19 09:05:42', '2025-11-19 09:05:42'),
(19, 1, 'التسجيل واستخدام الحساب', '[\"يجب أن تُدخل بيانات صحيحة وكاملة عند إنشاء حساب جديد.\",\"المستخدم مسؤول عن سرية بيانات دخوله، وأي نشاط يتم من خلال حسابه.\",\"لا يُسمح بمشاركة الحساب مع أطراف أخرى أو استخدامه لأغراض غير قانونية.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(20, 1, 'الدورات والمحتوى', '[\"جميع الدورات المتاحة على المنصة مخصصة للاستخدام الشخصي فقط.\",\"يُمنع إعادة بيع أو مشاركة المحتوى التعليمي خارج المنصة بدون إذن خطي مسبق.\",\"المنصة غير مسؤولة عن أي استخدام غير قانوني للمحتوى من قبل المشتركين.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(21, 1, 'الدفع والاشتراكات', '[\"عند الاشتراك في أي دورة، يجب إتمام عملية الدفع عبر الوسائل المتاحة على المنصة.\",\"في حال الدفع الإلكتروني، يتم تفعيل الدورة فورًا.\",\"في حال التحويل البنكي، يتم التفعيل بعد التأكد من عملية الدفع.\",\"رسوم الاشتراك غير قابلة للاسترداد إلا في حالات خاصة تحددها الإدارة.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(22, 1, 'حقوق الملكية الفكرية', '[\"جميع المواد التعليمية، الفيديوهات، النصوص، الصور، والشعارات مملوكة للمنصة و/أو شركائها.\",\"يمنع نسخ، إعادة إنتاج، أو توزيع أي محتوى دون إذن كتابي مسبق.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(23, 1, 'التزامات المستخدم', '[\"الالتزام بالأدب والاحترام عند التفاعل مع المدربين أو الطلاب الآخرين.\",\"عدم نشر أي محتوى مسيء، غير لائق، أو مخالف للقوانين.\",\"عدم محاولة اختراق أو تعطيل عمل المنصة.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(24, 1, 'إخلاء المسؤولية', '[\"المنصة تسعى لتقديم محتوى تعليمي بجودة عالية، لكنها غير مسؤولة عن أي نتائج سلبية أو فشل في تحقيق الأهداف التعليمية بسبب سوء استخدام المتدرب.\",\"قد تتغير بعض المعلومات أو الخدمات دون إشعار مسبق.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(25, 1, 'التعديلات على الشروط', '[\"تحتفظ المنصة بحقها في تعديل أو تحديث هذه الشروط والأحكام في أي وقت.\",\"استمرار استخدامك للمنصة بعد التعديلات يُعتبر موافقة ضمنية على التحديثات.\"]', '2025-11-23 09:36:36', '2025-11-23 09:36:36'),
(33, 334, 'التسجيل واستخدام الحساب', '[\"يجب أن تُدخل بيانات صحيحة وكاملة عند إنشاء حساب جديد.\",\"المستخدم مسؤول عن سرية بيانات دخوله، وأي نشاط يتم من خلال حسابه.\",\"لا يُسمح بمشاركة الحساب مع أطراف أخرى أو استخدامه لأغراض غير قانونية.\"]', '2025-12-02 12:45:27', '2025-12-02 12:45:27'),
(34, 334, 'الدورات والمحتوى', '[\"جميع الدورات المتاحة على المنصة مخصصة للاستخدام الشخصي فقط.\",\"يُمنع إعادة بيع أو مشاركة المحتوى التعليمي خارج المنصة بدون إذن خطي مسبق.\",\"المنصة غير مسؤولة عن أي استخدام غير قانوني للمحتوى من قبل المشتركين.\"]', '2025-12-02 12:45:27', '2025-12-02 12:45:27'),
